# Auto-generated by refactor: extracted verbatim from starter.py (factory + blueprints split).
from flask import Blueprint, current_app, jsonify, request
from flask_login import current_user, login_required

from app.config import AI_RATELIMIT, BEDROCK_RATELIMIT
from app.extensions import _user_or_ip_key, db, limiter
from app.models import UserSession
from app.services.ai_coach import _fetch_coach_context, _run_coach_conversation, generate_coach_reply
from app.services.calculations import calculate_bmr, calculate_target, calculate_tdee, generate_nutrition_plan, generate_training_plan
from app.timeutil import app_date_of, app_today


bp = Blueprint("coach", __name__)


@bp.route("/chat", methods=["POST"])
@login_required
@limiter.limit(AI_RATELIMIT, key_func=_user_or_ip_key)
@limiter.limit(BEDROCK_RATELIMIT, key_func=_user_or_ip_key)  # generate_coach_reply Sonnet'te: daha sıkı tavan
def chat():
    data = request.get_json(silent=True) or {}

    required_fields = ["weight", "height", "age",
                       "gender", "goal", "fitness_level", "current_activity"]
    for field in required_fields:
        if not data.get(field):
            return jsonify({"reply": f"{field} alanı eksik"}), 400

    try:
        weight = float(data["weight"])
        height = float(data["height"])
        age    = int(data["age"])
    except ValueError:
        return jsonify({"reply": "Kilo, boy ve yaş sayısal olmalıdır."}), 400

    name             = current_user.username  # formdan değil, oturumdan al
    gender           = data["gender"]
    goal             = data["goal"]
    level            = data["fitness_level"]
    current_activity = data["current_activity"]
    user_message     = data.get("message", "")

    # Kullanıcının önceki kaydını çek
    previous_session = UserSession.query.filter_by(user_id=current_user.id)\
        .order_by(UserSession.created_at.desc())\
        .first()

    # Önceki veriler ve geçen süre
    previous_weight  = None
    previous_date    = None
    days_passed      = None

    if previous_session:
        previous_weight = previous_session.weight
        previous_date   = previous_session.created_at
        # Istanbul gün sınırına göre (CLAUDE.md); ham UTC farkı gece-yarısı
        # yakınında bir gün kayardı (F1.2).
        days_passed     = (app_today() - app_date_of(previous_date)).days

    bmr             = calculate_bmr(weight, height, age, gender)
    tdee            = calculate_tdee(bmr, current_activity)
    target_calories = calculate_target(tdee, goal)
    training_plan   = generate_training_plan(goal, level)
    nutrition_plan  = generate_nutrition_plan(goal, target_calories)
    coach_reply     = generate_coach_reply(
                          name, age, gender, weight, height,
                          goal, level, current_activity,
                          bmr, tdee, target_calories,
                          training_plan, nutrition_plan,
                          user_message,
                          previous_weight, days_passed
                      )
    
    new_session = UserSession(
        name=name, age=age, gender=gender,
        weight=weight, height=height,
        goal=goal, fitness_level=level,
        current_activity=current_activity,
        bmr=bmr, tdee=tdee,
        target_calories=target_calories,
        training_plan=training_plan,
        nutrition_plan=nutrition_plan,
        coach_reply=coach_reply,
        user_id=current_user.id
    )
    db.session.add(new_session)
    db.session.commit()

    # Karşılaştırma verisi frontend'e gönder
    comparison = None
    if previous_weight and days_passed is not None:
        diff = round(weight - previous_weight, 1)
        comparison = {
            "previous_weight" : previous_weight,
            "days_passed"     : days_passed,
            "weight_diff"     : diff
        }

    return jsonify({
        "bmr"            : round(bmr),
        "tdee"           : round(tdee),
        "target_calories": round(target_calories),
        "training_plan"  : training_plan,
        "nutrition_plan" : nutrition_plan,
        "coach_reply"    : coach_reply,
        "comparison"     : comparison
    })


@bp.route("/ask", methods=["POST"])
@login_required
@limiter.limit(AI_RATELIMIT, key_func=_user_or_ip_key)
def ask_coach():
    data     = request.get_json(silent=True) or {}
    question = (data.get("question") or "").strip()
    # Widget her istekte kullanıcının gördüğü sohbeti gönderir → kaynak-doğru.
    # Liste değilse None bırak ki _run_coach_conversation eski session'a düşsün.
    client_history = data.get("history")
    if not isinstance(client_history, list):
        client_history = None

    if not question:
        return jsonify({"error": "Bir soru yaz."}), 400

    # Bağlam toplama psycopg2-bağımlı fitx_mcp.server'a dokunur; local'de veya
    # geçici çökmede graceful degrade etsin diye sarmalanır — function-calling
    # akışı (FatSecret + SQLAlchemy) buna bağlı değil, yine de çalışır.
    try:
        context = _fetch_coach_context(current_user.id, question)
    except Exception:
        context = ""

    try:
        answer = _run_coach_conversation(current_user.id, question, context, client_history)
        return jsonify({"answer": answer})
    except Exception:
        current_app.logger.exception("Koç yanıtı üretilemedi")
        return jsonify({"error": "Yanıt şu an alınamadı, lütfen tekrar dene."}), 500
